+const navToggle = document.querySelector(".nav-toggle");
+const primaryNav = document.querySelector("#primary-navigation");
+const toast = document.querySelector("#toast");
+const countdown = document.querySelector("#countdown");
+const year = document.querySelector("#year");
+const newsletterForm = document.querySelector(".newsletter-form");
+const emailInput = document.querySelector("#email");
+const emailError = document.querySelector("#email-error");
+const formStatus = document.querySelector("#form-status");
+
+let toastTimer;
+
+function closeNavigation() {
+  navToggle.setAttribute("aria-expanded", "false");
+  primaryNav.classList.remove("is-open");
+  document.body.classList.remove("nav-open");
+}
+
+function showToast(message) {
+  clearTimeout(toastTimer);
+  toast.textContent = message;
+  toast.classList.add("is-visible");
+  toastTimer = window.setTimeout(() => {
+    toast.classList.remove("is-visible");
+  }, 3200);
+}
+
+function updateCountdown() {
+  const now = new Date();
+  const saleEnd = new Date(now);
+  saleEnd.setHours(23, 59, 59, 999);
+
+  const remaining = Math.max(0, saleEnd.getTime() - now.getTime());
+  const hours = Math.floor(remaining / 3600000);
+  const minutes = Math.floor((remaining % 3600000) / 60000);
+  const seconds = Math.floor((remaining % 60000) / 1000);
+
+  countdown.textContent = `${hours}h ${String(minutes).padStart(2, "0")}m ${String(seconds).padStart(2, "0")}s`;
+}
+
+function validateNewsletter(event) {
+  event.preventDefault();
+
+  emailError.textContent = "";
+  formStatus.textContent = "";
+  emailInput.removeAttribute("aria-invalid");
+
+  if (!emailInput.validity.valid) {
+    emailInput.setAttribute("aria-invalid", "true");
+    emailError.textContent = emailInput.validity.valueMissing
+      ? "Enter your email address to join the list."
+      : "Enter an email address in the format shopper@example.com.";
+    emailInput.focus();
+    return;
+  }
+
+  formStatus.textContent = "Thanks. You are on the early access list.";
+  newsletterForm.reset();
+}
+
+navToggle.addEventListener("click", () => {
+  const isOpen = navToggle.getAttribute("aria-expanded") === "true";
+  navToggle.setAttribute("aria-expanded", String(!isOpen));
+  primaryNav.classList.toggle("is-open", !isOpen);
+  document.body.classList.toggle("nav-open", !isOpen);
+});
+
+primaryNav.addEventListener("click", (event) => {
+  if (event.target instanceof HTMLAnchorElement) {
+    closeNavigation();
+  }
+});
+
+document.addEventListener("keydown", (event) => {
+  if (event.key === "Escape" && primaryNav.classList.contains("is-open")) {
+    closeNavigation();
+    navToggle.focus();
+  }
+});
+
+document.querySelectorAll(".add-cart").forEach((button) => {
+  button.addEventListener("click", () => {
+    showToast(`${button.dataset.product} added to cart.`);
+  });
+});
+
+newsletterForm.addEventListener("submit", validateNewsletter);
+
+year.textContent = String(new Date().getFullYear());
+updateCountdown();
+window.setInterval(updateCountdown, 1000);
